using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.SGR.RecuperacionPassword;using GraphApi.Services.SGR.RecuperacionPassword;namespace GraphApi.Controllers.SGR.RecuperacionPassword{    /// <summary>    /// Gestión de RecuperacionPasswords: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("SGR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre RecuperacionPasswords")]    public class RecuperacionPasswordController : Controller    {        private readonly IRecuperacionPasswordService _objService;        public RecuperacionPasswordController(IRecuperacionPasswordService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los RecuperacionPasswords, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="recuperacionPasswordID">RecuperacionPasswordID</param>        /// <param name="usuarioID">UsuarioID</param>        /// <param name="token">Token</param>        /// <param name="fechaGeneracion">FechaGeneracion</param>        /// <param name="fechaExpiracion">FechaExpiracion</param>        /// <param name="usado">Usado</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de RecuperacionPasswords</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar RecuperacionPasswords",            Description = "Devuelve RecuperacionPasswords aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadRecuperacionPassword>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadRecuperacionPassword>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? recuperacionPasswordID,            [FromQuery] int? usuarioID,            [FromQuery] string? token,            [FromQuery] DateTime? fechaGeneracion,            [FromQuery] DateTime? fechaExpiracion,            [FromQuery] bool? usado,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetRecuperacionPasswordsDynamic(                recuperacionPasswordID,                 usuarioID,                 token,                 fechaGeneracion,                 fechaExpiracion,                 usado,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo RecuperacionPassword.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del RecuperacionPassword a crear.</param>        /// <returns>El RecuperacionPassword recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear RecuperacionPasswords",            Description = "Inserta un nuevo RecuperacionPassword en la base de datos."        )]        [ProducesResponseType(typeof(clReadRecuperacionPassword), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadRecuperacionPassword>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateRecuperacionPassword objInput)        {            var vCreated = await _objService.CreateRecuperacionPassword(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de RecuperacionPassword.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del RecuperacionPassword.</param>        /// <returns>El RecuperacionPassword actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar RecuperacionPasswords",            Description = "Actualiza uno o varios campos de RecuperacionPassword existente."        )]        [ProducesResponseType(typeof(clReadRecuperacionPassword), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadRecuperacionPassword>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateRecuperacionPassword objInput)        {            var vUpdated = await _objService.UpdateRecuperacionPassword(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un RecuperacionPassword por su ID.        /// </summary>        [HttpDelete("{nRecuperacionPasswordID:int}")]        [SwaggerOperation(            Summary = "Eliminar RecuperacionPassword",            Description = "Borra un RecuperacionPassword si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nRecuperacionPasswordID)        {            var success = await _objService.DeleteRecuperacionPassword(nRecuperacionPasswordID);            return success ? NoContent() : NotFound();        }    }}